window.__finlexDocLoaded(232,{"id":232,"articles":[{"id":5518,"no":"问1","heading":"问：执行《小企业会计准则》的企业应当如何对增值税期末留抵退税业务相关现金流量进行列示？","text":"【发布日期：2022-06-21】\n答：执行《小企业会计准则》的企业按照《关于进一步加大增值税期末留抵退税政策实施力度的公告》（财政部 税务总局公告2022年第14号）等规定收到或缴回的增值税期末留抵退税相关现金流量，应当根据《小企业会计准则》有关规定进行列示。企业收到或缴回留抵退税款项产生的现金流量，属于经营活动产生的现金流量，应将收到的留抵退税款项有关现金流量在“收到其他与经营活动有关的现金”项目列示，将缴回并继续按规定抵扣进项税额的留抵退税款项有关现金流量在“支付的税费”项目列示。","seq":0,"links":[{"doc_id":72,"tier":"L1","score":94,"rel_kind":"companion","target_seq":0,"target_art_no":"第一条","dir":"out","note":"核心配套：财政部会计司官方实施问答"},{"doc_id":72,"tier":"L1","score":94,"rel_kind":"companion","target_seq":2,"target_art_no":"第三条","dir":"out","note":"实施问答（问1）：锚定第三条（条文主题匹配）"}]},{"id":5519,"no":"问2","heading":"问：执行《小企业会计准则》的企业作为个人所得税的扣缴义务人，根据《中华人民共和国个人所得税法》收到的扣缴税款手续费，应当如何进行会计处理？","text":"【发布日期：2021-11-02】\n答：执行《小企业会计准则》的企业作为个人所得税的扣缴义务人，根据《中华人民共和国个人所得税法》收到的扣缴税款手续费，应当计入“其他收益”科目，在利润表“营业收入”项目中反映。","seq":1,"links":[{"doc_id":72,"tier":"L1","score":94,"rel_kind":"companion","target_seq":2,"target_art_no":"第三条","dir":"out","note":"实施问答（问2）：锚定第三条（条文主题匹配）"},{"doc_id":73,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中华人民共和国个人所得税法》"}]}]});
